def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_prev, opp_prev = history[-1]
    opp_moves = [o for _, o in history]
    my_moves = [m for m, _ in history]

    def opp_defections_last(k):
        return sum(1 for x in opp_moves[-k:] if x == 'D')

    def opp_coops_last(k):
        return sum(1 for x in opp_moves[-k:] if x == 'C')

    if n == 1:
        return 'C' if opp_prev == 'C' else 'D'

    # Establish cooperation early unless heavily defected.
    if n < 5:
        if opp_prev == 'D' and opp_defections_last(n) >= 2:
            return 'D'
        return 'C'

    total_opp_def = sum(1 for x in opp_moves if x == 'D')
    total_my_def = sum(1 for x in my_moves if x == 'D')

    # Strong retaliation after repeated defection.
    if opp_defections_last(3) >= 3:
        return 'D'

    # Forgiving tit-for-tat-ish recovery.
    if opp_prev == 'C':
        if opp_defections_last(5) <= 1:
            return 'C'
        # Occasionally test cooperation after opponent's sustained cooperation.
        if opp_coops_last(5) >= 4 and rng.random() < 0.35:
            return 'C'
        return 'D' if rng.random() < 0.5 else 'C'

    # Opponent just defected.
    if opp_defections_last(2) >= 2:
        return 'D'
    grudge = total_opp_def - total_my_def
    if grudge >= 3:
        return 'D'
    if grudge <= -1 and rng.random() < 0.25:
        return 'C'
    return 'D' if rng.random() < 0.65 else 'C'

